const LOGO_B64 = "";
const MASCOT_B64 = "";

const W = 390, H = 844, GAP = 70;

// ---------- utilidades ----------
function bytes(b64){const s=atob(b64);const a=new Uint8Array(s.length);for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return a;}
function C(h){h=h.replace('#','');return {r:parseInt(h.substr(0,2),16)/255,g:parseInt(h.substr(2,2),16)/255,b:parseInt(h.substr(4,2),16)/255};}

// Paleta clara y amigable
const WHITE   = C('FFFFFF');
const PAGE    = C('F5FBF0');
const MINT    = C('E8F6E1');
const MINT2   = C('DCF0D0');
const LEAF    = C('97C459');
const GREEN   = C('4CAF50');
const GREEN_D = C('2E7D46');
const FOREST  = C('1B6B3A');
const INK     = C('1F3D2B');
const GREY    = C('7C8B80');
const GREY_L  = C('E4EDE6');
const LEMON   = C('FFF3C4');
const PEACH   = C('FFE2C7');
const SKY     = C('D8ECFB');
const ROSE    = C('FFE0E3');
const CORAL   = C('E8735E');
const LILAC   = C('EBE3FA');

let LOGO_HASH = null, MASCOT_HASH = null;

async function loadFonts(){
  await figma.loadFontAsync({family:"Inter",style:"Regular"});
  await figma.loadFontAsync({family:"Inter",style:"Bold"});
  try{ await figma.loadFontAsync({family:"Inter",style:"Semi Bold"}); }catch(e){}
}

function rect(p,x,y,w,h,fill,r,strokeCol,sw){
  const n=figma.createRectangle();
  n.resize(w,h);
  n.x=x;n.y=y;
  n.fills=[{type:"SOLID",color:fill}];
  n.cornerRadius=(r===undefined?0:r);
  if(strokeCol){n.strokes=[{type:"SOLID",color:strokeCol}];n.strokeWeight=(sw||1);n.strokeAlign="INSIDE";}
  p.appendChild(n);
  return n;
}
function circ(p,x,y,d,fill,strokeCol,sw){
  const n=figma.createEllipse();
  n.resize(d,d); n.x=x; n.y=y;
  n.fills=[{type:"SOLID",color:fill}];
  if(strokeCol){n.strokes=[{type:"SOLID",color:strokeCol}];n.strokeWeight=(sw||2);n.strokeAlign="INSIDE";}
  p.appendChild(n);
  return n;
}
function T(p,str,x,y,o){
  o=o||{};
  const t=figma.createText();
  t.fontName={family:"Inter",style:(o.bold?"Bold":"Regular")};
  t.characters=String(str);
  t.fontSize=(o.size||13);
  t.fills=[{type:"SOLID",color:(o.color||INK)}];
  if(o.lh) t.lineHeight={value:o.lh,unit:"PIXELS"};
  p.appendChild(t);
  t.y=y;
  if(o.cx!==undefined) t.x=o.cx-t.width/2;
  else if(o.rx!==undefined) t.x=o.rx-t.width;
  else t.x=x;
  return t;
}
function img(p,hash,x,y,w,h){
  const n=figma.createRectangle();
  n.resize(w,h); n.x=x; n.y=y;
  n.fills=[{type:"IMAGE",scaleMode:"FIT",imageHash:hash}];
  p.appendChild(n);
  return n;
}
function frame(name){
  const f=figma.createFrame();
  f.name=name; f.resize(W,H); f.clipsContent=true;
  f.cornerRadius=36;
  f.fills=[{type:"SOLID",color:WHITE}];
  return f;
}
function page(f){ rect(f,0,0,W,H,PAGE,0); }
async function status(f){
  T(f,"9:41",20,18,{size:13,bold:true,color:INK});
  const d=rect(f,W-72,18,52,14,GREY_L,7);
  T(f,"100%",0,17,{size:10,bold:true,color:GREY,cx:W-46});
}
function card(f,x,y,w,h,r){ return rect(f,x,y,w,h,WHITE,(r===undefined?22:r),MINT2,1.5); }
function pill(f,x,y,w,h,fill,label,col,size){
  rect(f,x,y,w,h,fill,h/2);
  T(f,label,0,y+h/2-((size||11)*0.72),{size:(size||11),bold:true,color:(col||FOREST),cx:x+w/2});
}
async function btn(f,x,y,w,h,label,fill,col,size){
  rect(f,x,y,w,h,(fill||GREEN),h/2);
  T(f,label,0,y+h/2-((size||16)*0.62),{size:(size||16),bold:true,color:(col||WHITE),cx:x+w/2});
}
function bar(f,x,y,w,pct,col,h){
  h=h||10;
  rect(f,x,y,w,h,GREY_L,h/2);
  rect(f,x,y,Math.max(h,w*pct),h,(col||LEAF),h/2);
}
function divider(f,x,y,w){ rect(f,x,y,w,1.5,GREY_L,1); }

// barra inferior amigable
async function nav(f,items,active,accent){
  accent = accent||GREEN;
  const nb=rect(f,0,H-96,W,96,WHITE,0);
  rect(f,0,H-96,W,2,MINT2,1);
  const n=items.length, step=W/n;
  for(let i=0;i<n;i++){
    const cx=step*i+step/2, on=(i===active);
    if(on) rect(f,cx-30,H-80,60,34,MINT,17);
    circ(f,cx-9,H-72,18,(on?accent:GREY_L));
    if(on) circ(f,cx-4,H-67,8,WHITE);
    T(f,items[i],0,H-40,{size:10,bold:on,color:(on?FOREST:GREY),cx:cx});
  }
}

// encabezado con titulo grande
function head(f,title,sub){
  rect(f,0,0,W,(sub?128:112),MINT,0);
  rect(f,0,(sub?108:92),W,40,MINT,24);
  rect(f,0,(sub?128:112),W,20,PAGE,0);
  T(f,title,22,52,{size:24,bold:true,color:FOREST});
  if(sub) T(f,sub,22,84,{size:13,color:GREEN_D});
}

// fila de lista
function row(f,x,y,w,title,sub,right,dotCol,rightCol){
  circ(f,x+14,y+13,34,(dotCol||MINT));
  T(f,title,x+58,y+13,{size:13,bold:true,color:INK});
  if(sub) T(f,sub,x+58,y+31,{size:11,color:GREY});
  if(right) T(f,right,0,y+20,{size:14,bold:true,color:(rightCol||GREEN_D),rx:x+w-14});
}

// tarjeta de estadistica
function stat(f,x,y,w,h,label,value,fill){
  rect(f,x,y,w,h,(fill||MINT),20);
  T(f,value,0,y+18,{size:22,bold:true,color:FOREST,cx:x+w/2});
  T(f,label,0,y+48,{size:10,color:GREEN_D,cx:x+w/2});
}

