(async () => {
  await loadFonts();
  figma.currentPage.name = "MPACKING - Mockups";
  LOGO_HASH   = figma.createImage(bytes(LOGO_B64)).hash;
  MASCOT_HASH = figma.createImage(bytes(MASCOT_B64)).hash;

  const groups = [
    { title: "USUARIO", fns: [u01,u02,u03,u04,u05,u06,u07,u08,u09,u10] },
    { title: "ADMINISTRADOR", fns: [a01,a02,a03] },
    { title: "RESTAURANTE", fns: [r01,r02,r03] },
    { title: "RECICLADOR", fns: [c01,c02,c03] }
  ];

  let rowY = 0;
  for (const g of groups) {
    const label = figma.createText();
    label.fontName = {family:"Inter", style:"Bold"};
    label.characters = g.title;
    label.fontSize = 34;
    label.fills = [{type:"SOLID", color: FOREST}];
    label.x = 0; label.y = rowY - 56;
    figma.currentPage.appendChild(label);

    let col = 0, line = 0;
    for (const fn of g.fns) {
      const fr = await fn();
      fr.x = col * (W + GAP);
      fr.y = rowY + line * (H + GAP + 56);
      figma.currentPage.appendChild(fr);
      col++;
      if (col === 5) { col = 0; line++; }
    }
    const lines = Math.ceil(g.fns.length / 5);
    rowY += lines * (H + GAP + 56) + 90;
  }

  figma.viewport.scrollAndZoomIntoView(figma.currentPage.children);
  figma.closePlugin("Listo: 19 mockups MPACKING creados.");
})();
